def power(a, b, m):
    return pow(a, b, m)

p = 61
exponent = (p - 1) // 3 # 20

# Count the number of cubic residues V != 0
count_residues = 0
cubic_residues = []

for V in range(1, p):
    if power(V, exponent, p) == 1:
        count_residues += 1
        cubic_residues.append(V)

print(f"Total number of non-zero cubic residues (should be 20): {count_residues}")
# print(f"Cubic residues: {cubic_residues}") # Too long to print

import math

p = 61

# 1. Calculate R2(r): Number of solutions to a^2 = r mod 61, a in {1, ..., 61}
def legendre_symbol(a, p):
    if a % p == 0:
        return 0
    return pow(a, (p - 1) // 2, p)

R2 = {}
for r in range(p):
    if r == 0:
        R2[r] = 1 # Only a=61 (or a=0 mod 61)
    else:
        ls = legendre_symbol(r, p)
        if ls == 1:
            R2[r] = 2 # Quadratic Residue
        else:
            R2[r] = 0 # Quadratic Non-Residue

# 2. Calculate S2_2(R): Distribution of a^2 + b^2 mod 61
S2_2 = {}
for R in range(p):
    count = 0
    for r1 in range(p):
        r2 = (R - r1) % p
        count += R2[r1] * R2[r2]
    S2_2[R] = count

# 3. Calculate R3(r): Number of solutions to c^3 = r mod 61, c in {1, ..., 61}
R3 = {}
for c in range(p):
    r = pow(c, 3, p)
    R3[r] = R3.get(r, 0) + 1

# 4. Calculate N_L(L0): Distribution of a^2 + b^2 + c^3 mod 61
N_L = {}
for L0 in range(p):
    count = 0
    # Iterate only over r3 that are cubic residues (i.e., keys in R3)
    for r3, count_r3 in R3.items():

        R = (L0 - r3) % p
        count += count_r3 * S2_2[R]
    N_L[L0] = count

# Print the entire distribution N_L
nl_list = [N_L[i] for i in range(p)]

print("Distribution of N_L(L0) for L0 = 0 to 60:")
print(nl_list)
print(f"Verification Sum: {sum(nl_list)}")

